<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import PhaseCompare from '../components/PhaseCompare.vue';import {create as review} from '../api/reviews';import {create as report} from '../api/reports';import {download} from '../api/client';import {useAsync} from '../hooks/useAsync';import {DECISIONS} from '../constants/enums';import {date} from '../utils/format';const props=defineProps<{data:Workspace;canWrite:boolean;isAdmin:boolean;refresh:()=>Promise<void>}>();const completed=computed(()=>props.data.runs.filter(r=>r.status==='completed'));const id=ref(''),note=ref(''),decision=ref('accepted');const active=computed(()=>completed.value.find(r=>r.id===id.value)||completed.value[0]);const {busy,error,execute}=useAsync();async function submit(){await execute(async()=>{await review({run_id:active.value?.id,note:note.value,decision:decision.value});note.value='';await props.refresh()})}async function publish(run_id:string){await execute(async()=>{await report({run_id,title:'中转网络韧性人工复核 · '+new Date().toISOString().slice(0,10)});await props.refresh()})};</script><template><PageHeading code="06 / RESILIENCE REVIEW" title="把瓶颈与绕行，放回各自口径。" description="记录边容量、割集、守恒和最短路证据，不能把最大流说成沿最短路发运。管理员再批准归档。"/><PhaseCompare v-if="active" :result="active.result"/><section class="paper" v-if="canWrite"><h2>提交韧性复核</h2><form class="grid-form" @submit.prevent="submit"><label>已完成推演<select aria-label="复核推演记录" :value="active?.id" @change="id=($event.target as HTMLSelectElement).value"><option v-for="r in completed" :key="r.id" :value="r.id">{{data.scenarios.find(s=>s.id===r.scenario_id)?.name}} · {{r.created_at.slice(11,19)}}</option></select></label><label>复核判断<select v-model="decision"><option value="accepted">接受并记录边界</option><option value="needs_attention">需要继续核查</option></select></label><label class="wide">依据与边界<textarea aria-label="依据与边界" required minlength="8" rows="3" v-model="note" placeholder="记录逐边ID、maxflow=mincut、节点守恒、停用影响与独立最短路，不作实际发运指令。"/></label><button :disabled="busy||!active">提交韧性复核</button></form></section><Notice v-if="error" error>{{error}}</Notice><section class="paper"><h2>人工复核记录</h2><Empty v-if="!data.reviews.length">运行完成后，先核对容量/守恒/路径三类证据，再提交判断。</Empty><article class="review-record" v-for="r in data.reviews" :key="r.id"><div><span :class="['status',r.decision]">{{DECISIONS[r.decision]}}</span><small>{{r.author}} · {{date(r.created_at)}}</small></div><p>{{r.note}}</p><button v-if="isAdmin&&r.decision==='accepted'&&!data.reports.some(p=>p.run_id===r.run_id)" class="secondary" :disabled="busy" @click="publish(r.run_id)">批准并归档</button></article></section><section class="paper"><h2>网络图册归档</h2><article class="report-row" v-for="p in data.reports" :key="p.id"><div><h3>{{p.title}}</h3><small>{{date(p.created_at)}} · {{p.published_by}}</small></div><button class="secondary" @click="execute(()=>download(p.id))">下载CSV　↓</button></article></section><details class="audit-details"><summary>操作留痕 / 最近{{data.audit.length}}条</summary><div class="table-scroll"><table><thead><tr><th>操作者</th><th>动作</th><th>状态</th></tr></thead><tbody><tr v-for="a in data.audit" :key="a.id"><td>{{a.actor}}</td><td>{{a.action}}</td><td>{{a.status}}</td></tr></tbody></table></div></details></template>
